CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email VARCHAR(320) NOT NULL UNIQUE,display_name VARCHAR(100) NOT NULL,password_hash TEXT NOT NULL,email_verified BOOLEAN NOT NULL DEFAULT FALSE,username VARCHAR(32) UNIQUE,first_name VARCHAR(100),last_name VARCHAR(100),birth_date DATE,location JSONB,school_or_work JSONB,avatar_file_id UUID,bio VARCHAR(255),is_blocked BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS email_verifications(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,code_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_email_verifications_user ON email_verifications(user_id,expires_at);
CREATE TABLE IF NOT EXISTS sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash BYTEA NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS chats(id BIGSERIAL PRIMARY KEY,type VARCHAR(16) NOT NULL CHECK(type IN('private','group','channel')),title VARCHAR(255),created_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS chat_members(chat_id BIGINT REFERENCES chats(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(32) NOT NULL DEFAULT 'member',joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(chat_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id BIGSERIAL PRIMARY KEY,chat_id BIGINT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES users(id),body TEXT,reply_to_id BIGINT REFERENCES messages(id),edited_at TIMESTAMPTZ,deleted_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_messages_chat_time ON messages(chat_id,created_at DESC);
CREATE TABLE IF NOT EXISTS files(id UUID PRIMARY KEY,owner_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(127) NOT NULL,size_bytes BIGINT NOT NULL,sha256 BYTEA NOT NULL,storage_path TEXT NOT NULL,encrypted BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS groups(id BIGSERIAL PRIMARY KEY,chat_id BIGINT NOT NULL UNIQUE REFERENCES chats(id) ON DELETE CASCADE,topics_enabled BOOLEAN NOT NULL DEFAULT FALSE,description TEXT);
CREATE TABLE IF NOT EXISTS channels(id BIGSERIAL PRIMARY KEY,chat_id BIGINT NOT NULL UNIQUE REFERENCES chats(id) ON DELETE CASCADE,is_public BOOLEAN NOT NULL DEFAULT FALSE,username VARCHAR(32) UNIQUE,description TEXT);
CREATE TABLE IF NOT EXISTS topics(id BIGSERIAL PRIMARY KEY,chat_id BIGINT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,icon VARCHAR(32),archived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,type VARCHAR(64) NOT NULL,payload JSONB NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,user_id BIGINT,action VARCHAR(100) NOT NULL,ip INET,request_id VARCHAR(80),metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
